  "媒体播放与前台应用使用分别计时，可能同时发生，不应相加。只累计独立媒体记录的播放采样区间；同一设备重叠区间合并，多台设备分别累计。应用或状态分组可能重叠。": "Media playback and foreground usage are measured separately and may overlap; do not add them. Only independent playback sample intervals count. Overlaps merge per device; different devices accumulate separately. App and state groups may overlap.",
  "截图附带的媒体状态不重复计时。暂停、缓冲和观察空隙不补齐；播放进度或媒体总长度不等于收听时长，远程播放也不代表手机发声。": "Media state attached to screenshots is not counted again. Pauses, buffering, and observation gaps are not filled. Playback position and media length are not listening duration; remote playback does not mean the phone produced sound.",
