  "最大输出 token 数": "Maximum output tokens",
  "输出 token 上限": "Output token limit",
  "1–128000。单次响应的上限，包含正文、HTML 及服务商计入的推理 token，不是固定生成长度、字数或图片大小。保存后生效。": "1–128000. Per-response limit including text, HTML, and provider-counted reasoning tokens. It is not a fixed response length, word count, or image size. Applies on save.",
  "允许本机模型免密访问": "Allow unauthenticated local models",
  "只适用于回环地址；容器中的“本机”指容器本身。": "Loopback addresses only. Inside a container, local means the container itself.",
