  "按当前协议填写 JSON 对象，整体替换。消息、工具与其他运行必需字段由 Mote 管理；已有值不会回显。": "Enter a JSON object for the current protocol. Replaces the whole object. Mote manages messages, tools, and required fields; existing values are hidden.",
  "允许在更改后的服务地址复用已保存的凭据": "Allow saved credentials at the changed service URL",
  "这会把保留的 API key、请求头或高级参数发送到当前填写的地址。也可以改为填写新值或清除旧值。": "Sends retained API keys, headers, or advanced parameters to the entered URL. Alternatively, replace or clear old values.",
  "测试连接会由中央节点发送少量合成内容，最多等待 30 秒，可能产生少量费用；不会读取资料库。测试不会保存草稿。": "Testing sends a small synthetic request from the central node, waits up to 30 seconds, and may incur a small charge. It does not read the archive or save the draft.",
