  "诊断、日志与高级生效配置": "Diagnostics, logs, and advanced active settings",
  "模型与记忆设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开设置页面或返回上级菜单时，未保存的输入会丢弃。": "Model and memory settings apply on save. Other preferences use a deployment draft and restart. Unsaved inputs are discarded when leaving Settings or returning to the parent menu.",
