  "已是最新版本，发布签名已验证。": "Up to date; release signature verified.",
  "查看版本说明与安装包": "View release notes and downloads",
  "上次检查：": "Last checked:",
  "在部署机的 Mote 目录执行。命令先校验下载并准备程序，再备份、切换和检查健康状态。新版启动失败时保留快照，使用回退命令恢复。": "Run in the Mote directory on the deployment host. The command verifies and prepares the download, then backs up, switches, and checks health. If startup fails, use rollback to restore the retained snapshot.",
  "需要回退时": "To roll back",
  "回退恢复升级前的数据快照；升级后的资料会另行保留。不要直接用旧程序打开已升级的数据。": "Rollback restores the pre-update snapshot and preserves newer data separately. Do not open upgraded data directly with an older program.",
  "此节点未由命名部署环境管理。请先按部署文档建立对应环境，再使用更新命令；本页面不会直接重启当前服务。": "This node is not managed by a named deployment profile. Set one up using the deployment guide before using update commands. This page does not restart the service.",
