  "服务商、协议或地址已改变，请确认复用已有凭据，或替换、清除已有凭据。": "Provider, protocol, or URL changed. Confirm credential reuse, or replace or clear credentials.",
  "模型设置暂不可用，请检查服务状态后重试。": "Model settings temporarily unavailable. Check service and retry.",
