  "自定义接口": "Custom endpoint",
  "选择接口协议，填写服务基址和支持工具调用的模型 ID。高级配置可设置请求头和厂商参数。": "Choose a protocol, base URL, and tool-capable model ID. Advanced settings support headers and provider parameters.",
  "DeepSeek 官方接口，保留其推理与多轮工具调用格式。模型 ID 以控制台为准。": "Official DeepSeek API preserving reasoning and multi-turn tool calls. Check the console for model IDs.",
  "阿里云 / 通义千问": "Alibaba Cloud / Qwen",
  "使用百炼 API key；工作空间与地域地址可按控制台修改，密钥必须与地域对应。": "Use a Model Studio API key. Adjust workspace and region URL to your console; the key must match the region.",
