  "智谱 / GLM": "Zhipu / GLM",
  "使用开放平台 API key；选择支持工具调用的模型，思考参数按该模型文档配置。": "Use an open-platform API key and a tool-capable model. Configure reasoning according to its documentation.",
  "月之暗面 / Kimi": "Moonshot / Kimi",
  "使用 Kimi 开放平台 API key；不同代际模型的思考参数不同，默认交给模型处理。": "Use a Kimi API key. Reasoning parameters vary by model generation; automatic is the default.",
  "使用 MiniMax API key。也可切换 Messages 协议并将地址改为 https://api.minimax.cn/anthropic。": "Use a MiniMax API key. For Messages, change the URL to https://api.minimax.cn/anthropic.",
  "百度智能云 / 千帆": "Baidu Cloud / Qianfan",
  "使用新版 API Key（Bearer）；不要填写旧版 OAuth access_token。模型须支持工具调用。": "Use the newer API Key (Bearer), not an old OAuth access_token. The model must support tools.",
  "腾讯云 / TokenHub": "Tencent Cloud / TokenHub",
  "腾讯新版模型服务，使用 TokenHub 新密钥；从旧混元平台迁移时需要同时更换地址和密钥。": "Tencent's newer model service uses a new TokenHub key. Migrating from legacy Hunyuan requires changing both URL and key.",
  "腾讯混元（原平台）": "Tencent Hunyuan (legacy)",
  "供已有混元账户使用；新接入建议选择 TokenHub，两个平台的密钥不能直接复用。": "For existing Hunyuan accounts. New integrations should use TokenHub; their keys are not interchangeable.",
  "硅基流动 / SiliconFlow": "SiliconFlow",
  "填写完整模型 ID；工具调用与思考能力取决于所选模型。": "Enter the full model ID. Tool and reasoning support depend on the model.",
  "讯飞 / 星火": "iFlytek / Spark",
  "使用 HTTP 服务的 APIPassword。预设为 X2 地址，其他版本请按控制台修改地址和模型 ID。": "Use the HTTP service APIPassword. X2 is the preset URL; adjust URL and model ID in the console for other versions.",
  "阶跃星辰 / StepFun": "StepFun",
  "使用开放平台 API key；Step Plan 套餐需改为 https://api.stepfun.com/step_plan/v1 并选择套餐可用模型。": "Use an open-platform API key. Step Plan requires https://api.stepfun.com/step_plan/v1 and a model available in your plan.",
  "默认使用 Responses；也可切换 Chat Completions。填写账户可用的模型 ID。": "Defaults to Responses; Chat Completions is also supported. Enter a model ID available to your account.",
  "使用原生 Messages 与工具调用，凭据为 Claude API key。": "Native Messages and tool calls using a Claude API key.",
  "Google 原生接口；使用 Gemini API key，保留工具调用中的思考签名。选择支持工具调用的模型。": "Native Google API with a Gemini key, preserving thought signatures in tool calls. Choose a tool-capable model.",
  "填写 Azure 资源的 https://资源名.openai.azure.com/openai/v1 地址；模型栏填写部署名称，密钥通过 api-key 请求头发送。": "Enter your Azure resource URL https://resource.openai.azure.com/openai/v1 and deployment name as model. The key is sent in the api-key header.",
  "使用 Responses 接口和 xAI API key；也可切换兼容 Chat Completions。": "Responses with an xAI key; compatible Chat Completions is also supported.",
  "使用 Chat Completions；选择支持函数调用的模型。": "Chat Completions; choose a function-calling model.",
  "Groq 官方兼容接口；模型的参数和工具能力以控制台说明为准。": "Official Groq-compatible API. Check the console for model parameters and tool capabilities.",
  "填写完整模型 ID；请选择支持 tools 的模型与路由。": "Enter the full model ID and choose a tools-capable model and route.",
  "地址属于中央节点所在机器。需先启动 Ollama 并安装支持工具调用的模型。": "This address is on the central host. Start Ollama and install a tool-capable model first.",
  "先在中央节点所在机器启动 LM Studio 服务，模型须支持工具调用。": "Start LM Studio on the central host first. The model must support tools.",
  "本机图片批量去重": "Bulk local image deduplication",
  "扫描开始时本机保存的全部采集图片，按时间从早到晚扫描，与上一张保留图比较；相似则标记为重复，否则更新保留图。应用或尺寸变化时重新开始比较，不限制时间间隔。只处理本机副本；已上传中央的记录仍然保留。待决定区独立保存在本机，不参与同步和自动清理，仍占用磁盘空间。": "Scans all local capture images present at start, oldest first, comparing with the last retained image. Similar images become candidates; otherwise the retained image advances. App or size changes reset comparison; no time-gap limit. Only local copies are affected; central records remain. Quarantine is local, excluded from sync and automatic cleanup, and still uses disk space.",
  "扫描和处理均在后台执行，可以离开本页。取消后已完成的处理保留，剩余记录留在原处。": "Scanning and processing run in the background. You may leave this page. Cancelling preserves completed work and leaves remaining records in place.",
