  "同应用连续采样归为一段；切换应用或间隔超过 5 分钟分段。仅按本页日期与现存截图分组，起止范围不代表使用时长。": "Continuous samples in one app form a session; app changes or gaps over 5 minutes start another. Groups use existing screenshots on this date. Time ranges do not indicate usage duration.",
