  "记录读取失败，请刷新重试": "Cannot read record. Refresh and retry.",
  "中央记录暂不可读取，请检查网络后重试": "Cannot read central record. Check network and retry.",
  "本机记录暂不可读取，请刷新重试；文件已保留": "Cannot read local record. Refresh and retry; file preserved.",
  "采集状态": "Collection state",
  "屏幕：{0}": "Screen: {0}",
  "媒体：{0}": "Media: {0}",
  "Mote · 采集状态": "Mote · Collection state",
  "你已停止采集，已有记录保留，同步按所选策略运行": "You stopped collection. Records are preserved; sync follows the selected policy.",
  "同步与恢复": "Sync and recovery",
  "手机负责采集，中央端负责归档。已上传的本机副本按保留时间清理。": "The phone collects; the central node archives. Uploaded local copies are removed after their retention period.",
  "正在读取本机同步状态…": "Loading local sync state…",
  "查看待上传队列": "View pending queue",
  "立即同步待发记录": "Sync pending records now",
  "从未确认的记录继续发送；上传中断只重发未确认记录。同一条记录重试不会生成重复副本。仍遵守 Wi-Fi 设置。": "Resumes from unacknowledged records. Interrupted uploads resend only those records without creating duplicates. Wi-Fi settings still apply.",
  "检查两端记录状态": "Check records on both ends",
  "只检查手机仍保留的采集记录在中央端是否可见；不会把“中央存在”直接当作上传确认，也不会删除或恢复记录。": "Checks whether records still retained on the phone are visible centrally. Central presence is not treated as upload acknowledgement; nothing is deleted or restored.",
  "全量补传 · 本机保留的记录": "Resend all retained local records",
  "重新上传本机保留的数据？": "Upload retained local data again?",
  "会重发本机仍保留的截图、OCR 原始事件、通知、设备事件、笔记及已启用来源的保留版本。中央端核验相同 ID 去重，继续补齐缺失数据。\n\n已从手机清理的数据无法补传。中央已删除或内容冲突的记录不会覆盖或恢复，暂停的来源不会启用。此操作可能产生较多流量，仍遵守网络设置。": "Resends retained screenshots, original OCR events, notifications, device events, notes, and retained revisions from enabled sources. Central ID checks deduplicate and fill gaps.\n\nData already cleaned from the phone cannot be resent. Centrally deleted or conflicting records are not overwritten or restored; paused sources stay paused. This may use substantial data; network settings still apply.",
  "开始补传": "Start resend",
  "尚未执行检查或全量补传": "No check or full resend performed yet",
  "停止本次检查 / 准备补传": "Stop this check / resend preparation",
  "已请求停止检查；已进入待发队列的记录按同步策略保留": "Stop requested. Records already queued remain according to sync policy.",
  "查看记录与冲突": "View records and conflicts",
  "查看来源同步状态": "View source sync state",
  "需要处理时：\n• 网络或服务暂不可用：自动模式退避重试，手动模式再次点同步。\n• 授权失效：重新连接同一节点后同步。\n• 同 ID 内容冲突 / 中央已删除：保留本机副本，跳过该条继续其他记录，不自动覆盖。\n• 等待 OCR：图片已归档不代表识别完成，识别结果会另行确认。\n\n中央端显示的是上次联系时的状态，不是手机实时状态。": "When attention is needed:\n• Network/service unavailable: automatic mode retries with backoff; manual mode needs another tap.\n• Authorization expired: reconnect the same node, then sync.\n• ID conflict / central deletion: keep the local copy and continue other records without overwriting.\n• Awaiting OCR: archived images do not prove recognition is complete; results are acknowledged separately.\n\nCentral status reflects the last contact, not live phone state.",
  "请先配置连接": "Configure a connection first",
  "正在读取存储状态": "Reading storage state",
