  "存储目录不匹配，已保留原选择和数据": "Storage directory mismatch. Original selection and data preserved.",
  "存储恢复记录存在，但位置指针缺失，请保留应用数据": "Storage recovery record exists but location pointer is missing. Preserve app data.",
  "无法创建本机存储目录": "Cannot create local storage directory",
  "存储目录不可为符号链接": "Storage directory cannot be a symbolic link",
  "存储位置已更新，请重试此操作": "Storage location updated. Retry this operation.",
  "正在检查原存储完整性": "Checking original storage integrity",
  "目标存储不可用": "Destination storage unavailable",
  "目标空间不足，原目录保持不变": "Insufficient destination space; original directory unchanged",
  "无法创建目标存储目录": "Cannot create destination directory",
  "无法读取原存储目录": "Cannot read original storage directory",
  "正在复制并校验文件 {0}/{1}": "Copying and verifying file {0}/{1}",
  "原存储包含无法迁移的条目": "Original storage contains entries that cannot be migrated",
  "复制校验失败，原数据已保留": "Copy verification failed; original data preserved",
  "正在验证目标记录与图片": "Verifying destination records and images",
  "存储迁移状态不一致，请保留应用数据": "Inconsistent migration state. Preserve app data.",
  "无法清理旧存储副本": "Cannot clean old storage copy",
  "旧目录包含未知子目录，副本已保留": "Old directory contains unknown subdirectories; copy preserved",
  "旧存储副本清理未完成": "Old storage cleanup incomplete",
  "当前连接没有查看此记录的权限，请检查连接凭据": "Connection cannot access this record. Check credentials.",
  "此记录已不存在，或中央节点版本尚不支持浏览": "Record missing or node version does not support browsing",
  "中央记录读取失败（HTTP {0}）": "Central record read failed (HTTP {0})",
  "中央节点未返回图片": "Node returned no image",
  "记录响应超过大小上限": "Record response exceeds size limit",
  "无媒体状态": "No media state",
  "媒体会话": "Media session",
  "媒体采集未启用": "Media collection not enabled",
  "媒体等待授权": "Media awaiting authorization",
  "媒体暂不可用": "Media temporarily unavailable",
  "播放中": "Playing",
  "缓冲中": "Buffering",
  "连接中": "Connecting",
  "调整进度": "Seeking",
  "切换内容": "Changing content",
  "后台": "Background",
  "输出未知": "Output unknown",
  " · 等待充电": " · Waiting for power",
  "OCR 待处理{0}": "OCR pending{0}",
  "OCR 状态未知（历史记录）": "OCR unknown (historical record)",
  "连接或同步策略已变化，本次操作已停止；请重新发起": "Connection or sync policy changed. Operation stopped; start again.",
  "正在准备全量补传…": "Preparing full resend…",
  "已安排补传 {0} 条本机采集记录及 {1} 个保留来源版本；实际上传进度见下方同步状态。冲突和中央已删除记录保持隔离。": "Queued {0} local captures and {1} retained source revisions for resend. See sync status below. Conflicts and centrally deleted records remain isolated.",
  "检查完成：中央可见 {0} 条，不可见 {1} 条。检查范围为手机仍保留的采集记录；不可见可能是缺失、删除或无权限，不会自动恢复。来源快照由全量补传时核验。": "Check complete: {0} visible centrally, {1} not visible. Covers captures still retained on the phone. Not visible may mean missing, deleted, or unauthorized; nothing is restored automatically. Full resend verifies source snapshots.",
  "检查失败：连接授权失效，请重新连接同一节点后重试": "Check failed: authorization expired. Reconnect the same node and retry.",
  "中央节点尚不支持两端检查，请升级中央端代码；未修改本机状态": "Node does not support two-sided checks. Upgrade it; local state unchanged.",
  "检查响应未确认": "Check response unconfirmed",
  "检查响应缺失": "Check response missing",
  "已检查 {0} 条 · 中央可见 {1} · 不可见 {2}": "Checked {0} records · Visible {1} · Not visible {2}",
  "操作未完成，已完成的步骤保留；请检查网络或存储。本次手动操作可再次点击继续，未删除任何副本。": "Operation incomplete; completed steps preserved. Check network or storage and tap again to continue. No copies were deleted.",
  "操作已请求；重复点击会合并，等待网络条件或当前操作完成": "Operation requested. Repeated taps merge; waiting for network conditions or current work.",
  "图片保存位置": "Image storage location",
  "本机保存待同步、待 OCR 与保留期内的记录和图片。上传后仍可回看，到期才清理。": "Locally retains pending sync/OCR records and images within retention. Uploaded records remain browsable until expiry.",
  "选择内部应用空间，或系统提供的本机／存储卡应用空间。迁移会自动暂停处理、复制并验证已有记录，然后继续原来的采集与同步。模型、草稿、设置及来源缓存保留在内部空间。": "Choose internal app storage or system-provided local/SD-card app storage. Migration pauses processing, copies and verifies records, then resumes prior collection and sync. Models, drafts, settings, and source cache stay internal.",
  "默认明文保存：记录和索引为 JSON，图片保留原始格式。开发者选项可开启本地内容加密，也可批量解密旧文件。这些是本应用专用目录，不是共享相册；卸载应用会删除本机文件。移除存储卡后会停止使用该位置并提示，不会切到空目录；重新连接后可恢复。": "Plaintext by default: JSON records/indexes and original image formats. Developer options can enable encryption or decrypt old files. These are private app directories, not a shared album; uninstalling deletes local files. Removing a card stops access with a notice, without switching to an empty directory. Reconnect to recover.",
  "正在读取存储位置…": "Loading storage locations…",
  "当前保存位置\n{0}": "Current location\n{0}",
  "位置不可用：{0}\n已保留原位置，请重新连接原介质后重试。": "Location unavailable: {0}\nOriginal location retained. Reconnect the original medium and retry.",
  "（当前）": "(current)",
  "{0}{1}\n可用 {2}\n{3}": "{0}{1}\nAvailable {2}\n{3}",
  "无法读取系统存储位置：{0}": "Cannot read system storage locations: {0}",
  "刷新存储状态": "Refresh storage state",
  "迁移本机保存位置": "Migrate local storage",
  "迁移到{0}：\n{1}\n\n已有图片、待 OCR 结果和队列记录会一起迁移。验证成功后切换位置并清理旧副本。中央归档位置保持不变。": "Migrate to {0}:\n{1}\n\nImages, pending OCR results, and queue records move together. After verification, switch locations and clean the old copy. Central archive location stays unchanged.",
  "迁移并应用": "Migrate and apply",
  "正在迁移并验证记录，请保持存储介质连接…": "Migrating and verifying records. Keep storage connected…",
