  "系统可能限制后台运行": "System may restrict background operation",
  "无障碍截图：{0}\n媒体通知使用权：{1}\n投屏：{2}\n通知：{3}\n使用情况：{4}\n电池优化：{5}\n自启动：系统未提供可靠查询，请在系统设置确认。": "Accessibility screenshots: {0}\nMedia notification access: {1}\nProjection: {2}\nNotifications: {3}\nUsage access: {4}\nBattery optimization: {5}\nAutostart: no reliable system query; confirm in system settings.",
