  "Android 通过通知使用权开放通知与媒体会话。开启通知采集后，Mote 会保存应用公开的标题、正文、持续状态以及更新和移除事件，并按同步策略上传。设备事件单独记录亮屏、熄屏和锁定状态。各来源需单独开启并点击开始；应用的“不记录”和“仅活动”规则仍适用。系统可能隐藏敏感通知；Mote 不回复通知、不控制播放。": "Android exposes notifications and media sessions through notification access. When notification collection is enabled, Mote saves public titles, text, ongoing state, updates, and removals, then uploads by policy. Device events separately record screen and lock states. Enable each source and tap Start. Exclude and activity-only app rules still apply. Sensitive notifications may be hidden; Mote never replies or controls playback.",
