  "\n统计口径与限制\n已保存表示本机入队成功；已上传表示节点已确认收到。待 OCR 的图片在确认上传后仍会保留，补做结果也同步成功后才清理。被过滤的画面不会入队。暂停是原因变更次数，不等于丢弃截图次数；请求可能因系统/进程中断没有后续结果。统计与队列分开持久化，进程在两次写入之间终止时累计数可能少记；当前队列数量包含待识别和同步失败保留的图片。\n": "\nDefinitions and limits\nSaved means queued locally; uploaded means acknowledged by the node. Pending OCR images remain after upload until OCR results also sync. Filtered frames are not queued. Pause counts track reason changes, not discarded screenshots. Interrupted requests may have no outcome. Statistics and queues persist separately, so termination between writes can undercount totals. Queue counts include pending OCR and failed-sync images.\n",
  "文件字节合计不是 Android 系统的安装占用；不含 APK、系统配额或其他分区。目录仅可由本应用读取，不是共享相册。": "File bytes are not Android installation usage; APKs, system quotas, and other partitions are excluded. Directories are private to this app, not shared albums.",
  "统计或队列暂不可读取，不能按零展示；原始文件保留，请查看支持诊断。": "Statistics or queue unreadable; cannot display zero. Originals preserved. Check support diagnostics.",
  "本机保留记录（第 {0} 页，每页 10 条；图片与文字请打开采集记录）": "Locally retained records (page {0}, 10 per page; open Capture records for images and text)",
