  "记录 ID：{0}\n创建：{1}\n条目字节：{2}\n本机仍保留此记录；下方历史同一 ID 可关联上传失败和确认。图片与文字可从采集记录查看。": "Record ID: {0}\nCreated: {1}\nEntry bytes: {2}\nThis record remains local. Match its ID with failure and acknowledgement history below. Images and text are in Capture records.",
