  "采集服务未连接，请打开手机应用恢复权限": "Collector disconnected. Open the phone app to restore permission.",
  "选择要归档的日历与文件。": "Select calendars and files to archive.",
  "连接本机日历": "Connect local calendar",
  "选择一个文件": "Select a file",
  "选择文件目录": "Select file directory",
  "选择录音目录 · 原件归档": "Select audio directory · Archive originals",
  "立即扫描并同步": "Scan and sync now",
  "正在调度扫描与同步…": "Scheduling scan and sync…",
  "来源限制与同步说明": "Source limits and sync",
  "来源说明": "About sources",
  "默认扩展名 md/txt/json/csv/ics，正文只接受 UTF-8；单文件 100 KiB、100000 字符，单次最多 200 项和 4 MiB，来源缓存最多 64 MiB（也遵守采集与存储中的队列上限）。超限或扫描不完整会提示，绝不把漏扫项当作删除。\n系统后台任务约每 15 分钟检查一次来源各自的间隔；省电或强行停止可能推迟，重新打开应用可恢复。原件归档每文件最多 512 MiB，Mote 文件暂存最多 1 GiB；自动等待稳定后上传，断网续传。引用模式不读取原件，不受原件大小限制。": "Default extensions: md/txt/json/csv/ics, UTF-8 text only. Limits: 100 KiB/100000 characters per file; 200 items/4 MiB per scan; 64 MiB source cache, also constrained by queue capacity. Limits and incomplete scans are reported; missed items are never inferred deleted.\nBackground jobs check source intervals roughly every 15 minutes. Power saving or force-stop may delay them; reopening can recover. Original archives allow 512 MiB per file and 1 GiB staging, wait for stable files, and resume offline uploads. Reference mode reads no original and has no original-size limit.",
