  "本地删除不影响中央原件；上传后仅清理 Mote 暂存，保留手机原文件。仅同步新增以首次完整清单为基线，重启不会重置。": "Local deletion does not affect central originals. Upload cleanup removes only Mote staging, preserving phone originals. New-only sync uses the first complete inventory as its baseline; restarting does not reset it.",
