  "更新未完成，请重试；旧应用和数据保留": "Update incomplete. Retry; old app and data preserved.",
  "正在刷新已保存连接…": "Refreshing saved connection…",
  "读取当前连接失败，请重新打开此页重试": "Cannot read connection. Reopen this page and retry.",
  "正在读取已保存连接…": "Loading saved connection…",
  "无法读取已保存连接，请检查本机存储后重试": "Cannot read saved connection. Check local storage and retry.",
  "连接中央节点": "Connect central node",
  "先在中央网页生成一次性邀请。扫码、选择 JSON 文件或粘贴邀请后，核对节点再确认连接；不会自动开始截图。邀请有效期 10 分钟，请勿分享。": "Generate a single-use invitation on the central web page. Scan, select JSON, or paste it, then review and confirm the node. Screenshots do not start automatically. Invitations expire in 10 minutes; do not share them.",
  "复制本设备 ID": "Copy device ID",
  "已复制设备 ID，不含凭据": "Device ID copied; no credentials included",
  "扫描连接二维码": "Scan connection QR code",
  "选择连接 JSON 文件": "Select invitation JSON",
  "粘贴 JSON 或 mote://connect…": "Paste JSON or mote://connect…",
  "开发调试：允许本机 loopback HTTP 邀请": "Development: allow loopback HTTP invitations",
  "解析并核对节点": "Parse and review node",
  "还没有解析邀请。外部链接只填入此页，不会自动连接。": "No invitation parsed. External links only fill this page; they do not connect automatically.",
  "确认连接此节点": "Confirm connection to this node",
  "确认连接节点": "Confirm node connection",
  "{0}\n\n将使用已有设备 ID 和当前采集设置。只获取这台设备的采集凭据；设置、队列和模型不会清空。同节点重新配对将使用新凭据继续同步本机待上传截图、笔记和来源。首次连接将把尚未绑定的本机截图、笔记与来源记录绑定到上方节点，并按已选择的同步方式发送。请确认这是你自己的档案地址。已经绑定其他节点的待同步记录不能改投此处。": "{0}\n\nUses your existing device ID and collection settings, obtaining a device-only credential without clearing settings, queue, or models. Re-pairing the same node resumes pending records with new credentials. First pairing binds unbound screenshots, notes, and sources to this address and sends according to your sync mode. Confirm it is your archive. Pending data bound elsewhere cannot be redirected here.",
  "连接": "Connect",
  "正在兑换邀请并校验设备身份…": "Redeeming invitation and verifying device…",
  "连接成功：{0}": "Connected: {0}",
  "连接成功，已自动应用新连接并恢复原采集状态。": "Connected. New connection applied and previous collection state restored.",
  "恢复中断的连接确认": "Recover interrupted pairing",
  "正在读取待恢复连接…": "Loading recoverable connection…",
  "恢复已兑换连接": "Recover redeemed connection",
  "{0}\n\n将重新联网校验已兑换并加密保存的凭据。确认后，尚未绑定的本机记录会绑定到上方节点并按同步设置发送。": "{0}\n\nReverifies the redeemed, encrypted credential online. After confirmation, unbound local records are assigned to this node and sent according to sync settings.",
  "恢复": "Recover",
  "正在重新校验设备连接…": "Reverifying device connection…",
  "中断的连接已恢复。": "Interrupted connection recovered.",
  "测试已保存的连接": "Test saved connection",
  "正在测试节点和设备凭据…": "Testing node and device credentials…",
  "本设备采集权限": "This device's collector access",
  "手工配置的管理员权限": "Manually configured owner access",
  "连接正常 · {0}": "Connection valid · {0}",
  "未测试": "Not tested",
  "{0}\n状态记录时间：{1}": "{0}\nState recorded at: {1}",
  "一次性码已被兑换但网络校验中断时，原配置保持不变；可重试同一邀请，或点击“恢复中断的连接确认”使用本机加密保存的兑换结果；若一次性码已消耗但未收到响应，请重新生成绑定设备的邀请。连接失败信息不会包含令牌或邀请内容。": "If redemption succeeded but verification was interrupted, original settings remain. Retry the same invitation or recover its encrypted local result. If the code was consumed without a response, generate another invitation bound to this device. Failure messages exclude tokens and invitation contents.",
  "还没有解析有效邀请。": "No valid invitation parsed yet.",
  "将连接：{0}\n有效至：{1}\n确认前不会发送网络请求。": "Connect to: {0}\nValid until: {1}\nNo network request before confirmation.",
  "邀请已解析，请核对节点并确认连接。当前连接尚未更改。": "Invitation parsed. Review the node and confirm; current connection unchanged.",
  "当前节点：{0}\n设备 ID：{1}\n已有设备请让中央生成绑定此设备 ID 的邀请；设备身份不会重置。": "Current node: {0}\nDevice ID: {1}\nFor an existing device, generate an invitation bound to this ID. Device identity will not reset.",
  "连接已更新": "Connection updated",
  "正在读取所选连接文件…": "Reading selected invitation file…",
  "将连接：{0}\n有效至：{1}\n请确认后连接。": "Connect to: {0}\nValid until: {1}\nConfirm to connect.",
  "连接文件已解析，尚未联网。": "Invitation parsed; no network request yet.",
  "凭据持久保存失败，恢复记录仍保留。请释放空间后恢复连接，不要卸载应用。": "Credential persistence failed; recovery record retained. Free space and recover the connection. Do not uninstall.",
  "没有可恢复的兑换结果，请重新生成邀请。": "No redeemed result to recover. Generate another invitation.",
  "尚未测试连接": "Connection not tested yet",
  "上次连接测试成功（不是持续在线保证）": "Last connection test passed (not a guarantee of continuous connectivity)",
  "邀请格式或节点不安全。请使用中央生成的 JSON/二维码；公网节点须为 HTTPS。": "Unsafe node or invalid invitation. Use centrally generated JSON/QR. Public nodes require HTTPS.",
  "邀请已失效、已使用或不匹配，请重新生成。": "Invitation expired, used, or mismatched. Generate another.",
  "中央已有此设备 ID。请用上方设备 ID 生成绑定邀请，再试一次；不会更换设备身份。": "Device ID already exists centrally. Generate an invitation bound to the ID above and retry. Identity will not change.",
  "本机有尚未绑定节点的资料，请确认档案地址后再连接。": "Unbound local data exists. Confirm the archive address before connecting.",
  "仍有截图/笔记/来源待同步或已准备提交的草稿，不能切换节点。请先同步原节点。": "Pending screenshots, notes, sources, or prepared drafts prevent switching nodes. Sync to the original node first.",
  "另一次设置操作尚未完成，请稍候再试。": "Another settings operation is unfinished. Wait and retry.",
