  "客户端配置": "Client configuration",
  "迁移采集、应用规则、同步、模型和诊断设置。系统权限和来源文件授权需在新设备重新授予。": "Migrate collection, app rules, sync, model, and diagnostics settings. Grant system and source-file permissions again on the new device.",
