  "导入配置 JSON": "Import configuration JSON",
  "备份本机仍保留的截图、应用活动、通知、媒体和随手记。ZIP 为明文，不含中央归档、来源文件原件、未提交草稿或模型文件。": "Back up screenshots, activity, notifications, media, and notes still retained locally. ZIP is plaintext and excludes central archives, source originals, unsubmitted drafts, and model files.",
