  "{0} 个来源同步需要处理 · 待发 {1} 条；请在来源页面检查权限或连接": "{0} sources need attention · {1} pending; check permissions or connections on the Sources page.",
  "仍有 {0} 条待发及 {1} 项来源设置待确认；暂停或权限不可用的来源需恢复后同步": "{0} records and {1} source settings still need attention; resume paused sources or restore permissions to sync.",
  "当前待发已确认 · {0} 张图片等待本机 OCR，完成后继续同步": "Pending records acknowledged · {0} images await local OCR and will sync when ready.",
  "当前待发记录已获中央确认；这不表示两端保留数量相同": "The central node acknowledged all pending records; this does not mean both sides retain the same count.",
