  "允许响应必须显式包含 rectangles 数组（无敏感区用空数组）": "An allow response must explicitly include a rectangles array (empty when there are no sensitive regions)",
  "图片去重诊断": "Image deduplication diagnostics",
  "仅保留开启诊断后命中的图片对。图片已完成隐私检查和遮罩，仅在本机保存，不会同步。": "Only image pairs detected after diagnostics are enabled are retained. Images have passed privacy checks and masking; they stay on this device and are never synced.",
  "最多 20 组、32 MiB，保存期限 24 小时。读取时清理过期记录；系统休眠可能延后后台清理。关闭诊断后清空。": "Up to 20 pairs and 32 MiB, retained for 24 hours. Expired records are removed when read; system sleep may delay background cleanup. Turning diagnostics off clears them.",
  "清空全部诊断图片": "Clear all diagnostic images",
  "本机保留 {0} 组去重诊断": "{0} local deduplication pairs",
  "诊断已关闭，临时图片已清空。可在开发者选项中开启。": "Diagnostics are off and temporary images have been cleared. Enable them in developer options.",
  "暂无图片对。开启后，下一次采集到重复画面时会在这里显示。": "No image pairs yet. After enabling diagnostics, the next duplicate capture will appear here.",
