  "先在本机记录，准备好再连接": "Start locally; connect when ready",
  "无需服务端也能采集和保存随手记。连接后按你选择的策略上传。": "Capture and save quick notes without a server. Once connected, uploads follow your chosen policy.",
  "连接节点": "Connect a node",
