  "继续记录": "Keep recording",
  "从一条想法，到完整的上下文": "From one idea to its full context",
  "记下想法、心情与灵感": "Capture ideas, feelings, and inspiration",
  "管理本地来源": "Manage local sources",
  "连接文件、目录和日历": "Connect files, folders, and calendars",
  "查看本机统计": "View local statistics",
  "了解采集与队列的状态": "Check capture and queue status",
  "先过滤，再保存。采集范围和隐私规则始终由你决定。": "Filter before saving. You control capture scope and privacy rules.",
  "关闭窗口后仍驻留菜单栏；停止采集后，已有记录仍按上传策略同步；退出应用后暂停。": "Mote stays in the menu bar when the window closes. Stopping capture keeps existing records syncing under your policy; quitting pauses sync.",
  "管理隐私": "Manage privacy",
  "按天回看": "Browse by day",
  "查看这台设备保存的截图、同步进度与识别文字。": "View screenshots, sync progress, and recognized text from this device.",
  "记录位置": "Record location",
  "本机待同步 / 待 OCR": "Local pending sync / OCR",
  "展示方式": "Display",
  "全部截图": "All screenshots",
  "Session 按本机 / 中央现存截图分别分组：同应用连续采样归为一段，切换应用或间隔超过 5 分钟即分段。起止范围不代表使用时长。": "Sessions group existing local and central screenshots separately. Consecutive samples from the same app form a session; switching apps or a gap over 5 minutes starts another. The time span is not usage duration.",
  "‹ 返回 Session": "‹ Back to sessions",
  "记录详情": "Record details",
  "关闭详情": "Close details",
  "本机只保留未完成同步或等待 OCR 的图片。已完成的记录可在“中央已归档”查看；关闭采集不会自动删除历史截图。": "This device retains only images pending sync or OCR. Completed records are available under Central archive; stopping capture does not delete historical screenshots.",
  "留住此刻": "Save this moment",
  "给生活留一句注脚。先保存到本机，再按你的上传策略同步。": "Leave a note for your future self. Save locally first, then sync under your upload policy.",
  "文字记录": "Text note",
  "此刻想记什么？": "What would you like to remember?",
  "心情": "Mood",
  "可选": "Optional",
  "每一条随手记都会先安全写入本地队列。已同步的记录可在中央仓库中查看。": "Every quick note is safely written to the local queue first. Synced notes are available in the central archive.",
  "连接更多日常": "Connect more of your day",
  "选择你希望归档的文件、目录和日历，Mote 会持续检查变化。": "Choose files, folders, and calendars to archive. Mote keeps checking for changes.",
  "仅读取你主动选择的内容。未连接节点时也会保留到本机。": "Only content you select is read. Records remain local while disconnected.",
  "选择目录": "Choose folder",
  "连接系统日历": "Connect system calendar",
  "连接 Coding Agent": "Connect coding agent",
  "采集所选 Agent": "Collect selected agents",
  "支持本机 Claude Code、Codex、Kimi Code。读取对话与工具记录，按下方首次同步及过滤规则归档，并在中央沉淀编码经验；不回写 Agent 配置。": "Supports local Claude Code, Codex, and Kimi Code. Archives conversations and tool records under the initial sync and filter rules below, and builds coding memories centrally. Agent configuration is never modified.",
  "选择一个已授权日历": "Choose an authorized calendar",
  "同步所选日历": "Sync selected calendar",
  "已连接的来源": "Connected sources",
  "立即检查并上传": "Check and upload now",
  "新来源使用以下规则。已有来源可在对应卡片中单独编辑。": "These rules apply to new sources. Edit existing sources on their individual cards.",
  "完成首次清点后，只同步新条目": "After the initial inventory, sync only new items",
  "保留方式": "Retention mode",
  "快照 · 保存文字": "Snapshot · Save text",
  "引用 · 仅元数据": "Reference · Metadata only",
  "检查间隔（秒）": "Check interval (seconds)",
  "文件来源扩展名（可补充）": "File extensions (extend as needed)",
  "文件来源每份 ≤100 KB UTF-8；跳过隐藏项和符号链接。": "Each source file is limited to 100 KB UTF-8; hidden items and symbolic links are skipped.",
  "排除相对路径（每行一项）": "Excluded relative paths (one per line)",
  "精确路径或目录前缀，适用于文件和编码对话来源。": "Exact paths or directory prefixes, for file and coding-conversation sources.",
  "上传前遮盖的确切文字（每行一项，可选）": "Exact text to redact before upload (optional; one per line)",
  "同时处理标题和正文。配置遮盖后不上传文件位置 URI，避免位置包含原文。": "Applied to titles and bodies. When redaction is configured, file location URIs are omitted to avoid exposing the original text.",
  "跟踪删除": "Track deletions",
  "仅完整成功扫描后标记范围内消失项；中央历史版本仍保留。默认关闭。": "Only a complete successful scan marks missing items within scope; central history is retained. Off by default.",
  "保存所选来源规则": "Save selected source rules",
  "结束编辑": "Finish editing",
  "来源权限与保存方式": "Source permissions and retention",
  "“快照”将文字保存到中央，“引用”只同步标题、位置和时间等元数据。截图应用过滤和视觉审查不适用于文字来源，请单独设置路径排除或文字遮盖。": "Snapshot saves text centrally; Reference syncs only metadata such as title, location, and time. Screenshot app filters and visual review do not apply to text sources. Configure path exclusions or text redaction separately.",
  "日历只读过去 30 天至未来 90 天内的所选日历，不修改系统日历。权限仅在点击连接日历时申请。App 驻留时持续检查本地变化，按统一上传策略同步；退出后暂停，下次打开恢复。": "Only the selected calendar from 30 days ago through 90 days ahead is read; system calendars are never modified. Permission is requested only when you connect a calendar. Mote checks local changes while running and follows the shared upload policy; quitting pauses checks until next launch.",
  "每来源待传上限 4000 版本 / 32 MiB。路径与待传正文只保存在本机私有来源目录，不进入支持包。更换节点或令牌使用独立同步状态；原节点待传版本不会发送到新节点。": "Each source can queue 4,000 versions / 32 MiB. Paths and pending text stay in a private local source directory and are excluded from support bundles. Changing nodes or tokens uses separate sync state; old pending versions are never sent to a new node.",
  "日历权限 ↗": "Calendar permission ↗",
  "管理连接、采集习惯，以及属于你的隐私边界。": "Manage connections, capture habits, and your privacy boundaries.",
  "连接与设备": "Connection and device",
  "中央节点、连接邀请与设备名称": "Central node, invitations, and device name",
  "上传与同步": "Upload and sync",
  "实时、定时、批量或仅手动上传": "Real-time, scheduled, batch, or manual uploads",
  "采样频率、文字识别、运行方式与本地队列": "Sampling, text recognition, operation, and local queue",
  "隐私与过滤": "Privacy and filters",
  "应用范围、遮挡区域与本地视觉审查": "App scope, masks, and local visual review",
