  "模型参数、性能诊断、支持包与数据迁移": "Model parameters, performance diagnostics, support bundles, and data migration",
  "采集过程中，连接和隐私设置会暂时锁定。停止采集后即可修改。": "Connection and privacy settings are locked during capture. Stop capture to edit them.",
  "本机统计": "Local statistics",
