  "运行概况": "Runtime overview",
  "队列与模型状态实时更新。": "Queue and model status update in real time.",
  "需要处理计数、耗时和 CPU 数据时，可开启本机诊断。": "Enable local diagnostics for counts, timing, and CPU data.",
  "诊断仅记录数值与固定阶段事件，不上传个人正文。": "Diagnostics record only numbers and fixed stage events; personal content is never uploaded.",
  "采样时长是同应用两次采样之间的设备活动估计，不等于你的注意力时间。": "Sampled duration estimates device activity between samples from the same app; it does not measure your attention.",
  "将这台 Mac 连接到由你掌管的中央节点。": "Connect this Mac to a central node you control.",
  "使用连接邀请": "Use a connection invitation",
  "在中央仓库的“设备连接”中生成邀请，然后粘贴或导入。": "Generate an invitation under Device connections in the central archive, then paste or import it.",
  "推荐": "Recommended",
  "请仅使用可信的中央地址。预览不会发送网络请求。": "Use only a trusted central address. Previewing sends no network requests.",
