  "每套配置独立保存服务、模型和凭据；在功能入口或默认分配中选择。": "Each profile stores its own provider, model, and credentials. Choose it at a feature entry point or in default assignments.",
  "配置名称": "Profile name",
  "使用中央服务器上 Codex CLI 的文件登录凭据。无需在这里填写 API key。Codex 仍会将选中的上下文发送到其模型服务；最长等待时间生效，输出 token 上限由 Codex 管理。": "Uses Codex CLI file-based login credentials on the central server. No API key is needed here. Codex still sends selected context to its model service. The timeout applies; Codex manages the output token limit.",
  "Codex Server 的单次模型请求由 App Server 内部管理，页面的“单次模型请求超时”不适用于内部模型生成；“Agent 总运行超时”可以留空，留空表示不设置 Mote 的总运行期限。输出 token 上限由 Codex 管理。": "Codex Server manages individual model generation requests inside App Server; the page's “single model request timeout” does not apply to internal generation. “Agent total runtime timeout” may be left blank, which disables Mote's total runtime deadline. Codex manages the output token limit.",
  "输出由 Codex 管理": "Output managed by Codex",
  "{0} / {1} 秒": "{0} / {1} seconds",
  "{0}；单次模型请求 {1} 秒；Agent 总运行 {2} 秒": "{0}; single model request {1} seconds; Agent total runtime {2} seconds",
  "将默认配置恢复为中央节点的启动环境或部署配置，其他配置和功能分配保留。当前未保存的草稿也会清空；不会修改部署文件。": "Restore the default profile from the central node's startup environment or deployment configuration. Other profiles and feature assignments remain. Unsaved drafts are cleared; deployment files are not modified.",
