  "待配置应用": "App configuration required",
  "Mote 使用独立的 CLI 配置。首次使用先创建应用，也可以填写已有应用的 App ID 和 App Secret。": "Mote uses a separate CLI configuration. Create an app, or enter an existing App ID and App Secret.",
