  "扫码登录并授权只读权限": "Sign in and authorize read-only access",
  "使用已有应用": "Use an existing app",
  "凭据仅发往当前中央节点。建议使用专用飞书应用；同一系统账号下，CLI 钥匙串可能与其他配置共享同一应用的凭据。": "Credentials are sent only to this central server. A dedicated Feishu app is recommended: CLI configurations under the same OS account may share keychain credentials for the same app.",
