  "所需只读权限与授权帮助": "Required read-only scopes and help",
  "文档读取、知识库读取、日历读取。应用管理员需先开通对应权限，再由用户扫码授权。": "Document, wiki and calendar read access. The app administrator must enable these scopes before the user authorizes them.",
