  "查看来源与归档": "View sources and archives",
  "断开连接": "Disconnect",
  "请先保存修改后的同步范围。": "Save the edited sync scope first.",
  "断开会停止读取并暂停这些来源，保留已归档资料。飞书端授权及 CLI 凭据仍保留，可在飞书中单独撤销。": "Disconnecting stops reads and pauses these sources while keeping archived content. Feishu authorization and CLI credentials remain; revoke access separately in Feishu.",
  "连接已断开，历史归档已保留。": "Disconnected. Historical archives are preserved.",
  "确认断开": "Confirm disconnect",
  "服务端尚未安装 Lark CLI。请点击安装，然后重新检测。": "Lark CLI is not installed on the server. Install it and check again.",
  "尚未配置飞书应用。请创建应用或填写已有应用凭据。": "No Feishu app is configured. Create one or enter existing app credentials.",
  "尚未连接飞书账号，请完成只读授权。": "No Feishu account is connected. Complete read-only authorization.",
  "读取权限未完整授予。请在飞书应用后台开通下方只读权限，然后重新授权。": "Read permissions are incomplete. Enable the listed read-only scopes in the app console and authorize again.",
  "授权链接已过期，请重新发起登录。": "The authorization link expired. Start a new sign-in.",
  "检测到账号变化，已暂停旧来源。请重新授权并选择同步范围。": "The account changed. Previous sources are paused. Authorize again and choose a sync scope.",
  "另一个操作正在进行，请稍后重试。": "Another operation is running. Try again shortly.",
  "操作超时。请检查服务端网络，或重新发起授权。": "The operation timed out. Check the server network or start authorization again.",
  "飞书 CLI 操作未完成。请检查网络、应用权限及服务账号的系统钥匙串访问，再重试。": "The Feishu CLI operation failed. Check the network, app permissions and the service account's keychain access, then retry.",
