  "如果无法打开，可复制链接到浏览器，或扫码。": "If the link cannot open here, copy it into a browser or scan the QR code.",
  "模型、记忆与飞书设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开设置页面或返回上级菜单时，未保存的输入会丢弃。": "Model, memory and Feishu settings take effect when saved. Other preferences require a deployment draft and restart. Unsaved input is discarded when you leave settings or return to the parent menu.",
