  "内容索引支持文本、PDF、Word 和音频；本机解析每文件最多 16 MiB，完整索引最多 100000 字符，超出后标记为轻量索引；轻量索引最多 8000 字符。音频需要本机转写服务。超限或扫描不完整不会推断文件已删除。\n系统后台任务约每 15 分钟检查一次；原件归档每文件最多 512 MiB，支持断网续传。仅文件目录不读取正文。": "Content indexing supports text, PDF, Word and audio. Local parsing supports files up to 16 MiB; full indexes up to 100000 characters, otherwise labeled lightweight; lightweight indexes up to 8000 characters. Audio requires a local transcription service. Incomplete scans never imply deletion.\nBackground checks run about every 15 minutes. Original archiving supports files up to 512 MiB and resumable transfers. Catalog mode does not read file content."
