  "使用中央服务器上 Codex CLI 的文件登录凭据。无需在这里填写 API key。Codex Server 的单次模型请求由 App Server 内部管理，页面的“单次模型请求超时”不适用于内部模型生成；“Agent 总运行超时”可以留空，留空表示不设置 Mote 的总运行期限。输出 token 上限由 Codex 管理。": "Uses Codex CLI file-based login credentials on the central server. No API key is needed here. Codex Server manages individual model requests inside App Server; the single model request timeout does not apply to internal generation. The Agent total runtime timeout may be left blank. Codex manages the output token limit.",
  "HTTP Provider：单次模型 API 请求的期限，包含一次生成和流式响应，不包含后续工具循环。Codex Server 不暴露内部单次模型请求，此项不适用。": "HTTP Provider: the deadline for one model API request, including one generation and streamed response but not later tool loops. Codex Server does not expose individual model requests; this does not apply.",
  "从一次 Agent 运行开始到完成，包含多次模型请求、工具调用和结果校验。Codex Server 可留空，留空表示不设置 Mote 的总运行期限。": "From the start of an Agent run to completion, including multiple model requests, tool calls and result validation. Codex Server may leave this blank to disable Mote's total runtime deadline.",
